__aicore__ inline int64_t SafeCeil(int64_t a, int64_t b)
{
    if (b == 0) {
        return 0;
    }
    return (a + b - 1) / b;
}

__aicore__ inline int64_t Align(int64_t a, int64_t b)
{
    if (b == 0) {
        return 0;
    }
    return SafeCeil(a, b) * b;
}

