/bin/zsh -lc "mkdir -p /tmp/kdev && cat > /tmp/kdev/top_p_v1.asc <<'EOF'
// top_p_renorm_probs: per-row threshold from the descending cumulative mass.
// One AI core per row. Exact key-space bisection on the predicate
//   R(t) = sum{x : x >= t} >= top_p.
#include <torch/extension.h>
#include <c10/core/DeviceGuard.h>
#include <torch_npu/csrc/core/npu/NPUStream.h>
#include <acl/acl.h>
#include \"kernel_operator.h\"

using namespace AscendC;

constexpr uint32_t ROWS = 32;
constexpr uint32_t V = 128256;
constexpr uint32_t CH = 2048;
constexpr int32_t NK = 3;      // ladder thresholds per round
constexpr int32_t NROUND = 15; // 4"'^15 > 2''^29 key span
constexpr uint32_t KEY_LO = 63u << 23;   // 2''^-64
constexpr uint32_t KEY_HI = 127u << 23;  // 1.0

__aicore__ inline float KeyToFloat(uint32_t key)
{
    float f;
    *reinterpret_cast<uint32_t *>(&f) = key;
    return f;
}

// Reduce CH fp32 lanes to one value: plain vector tree down to 64 lanes,
// then a scalar Kahan loop.
__aicore__ inline void ReduceToScalar(const LocalTensor<float> &acc, const LocalTensor<float> &tmp,
                                      float &outHi, float &outLo)
{
    LocalTensor<float> a = acc;
    uint32_t len = CH;
    while (len > 64) {
        uint32_t half = len >> 1;
        Add(tmp, a, a[half], half);
        PipeBarrier<PIPE_V>();
        for (uint32_t i = 0; i < half; i++) {
            a.SetValue(i, tmp.GetValue(i));
        }
        PipeBarrier<PIPE_S>();
        len = half;
    }
    float s = 0.0f, c = 0.0f;
    for (uint32_t i = 0; i < 64; i++) {
        float v = a.GetValue(i);
        float y = v - c;
        float t = s + y;
        c = (t - s) - y;
        s = t;
    }
    outHi = s;
    outLo = -c;
}

extern "C" __global__ __aicore__ void top_p_kernel(GM_ADDR probs, GM_ADDR topp, GM_ADDR out)
{
    uint32_t row = GetBlockIdx();
    if (row >= ROWS) {
        return;
    }
    TPipe pipe;
    TQue<TPosition::VECIN, 2> inQ;
    TBuf<TPosition::VECCALC> bMask;
    TBuf<TPosition::VECCALC> bZero;
    TBuf<TPosition::VECCALC> bTmp;
    TBuf<TPosition::VECCALC> bAcc;
    TBuf<TPosition::VECCALC> bRed;
    TBuf<TPosition::VECCALC> bScal;
    TBuf<TPosition::VECCALC> bTopp;
    pipe.InitBuffer(inQ, 2, CH * sizeof(float));
    pipe.InitBuffer(bMask, CH);
    pipe.InitBuffer(bZero, CH * sizeof(float));
    pipe.InitBuffer(bTmp, CH * sizeof(float));
    pipe.InitBuffer(bAcc, NK * CH * sizeof(float));
    pipe.InitBuffer(bRed, CH * sizeof(float));
    pipe.InitBuffer(bScal, 128 * sizeof(float));
    pipe.InitBuffer(bTopp, 128 * sizeof(float));

    GlobalTensor<float> pG, oG, tG;
    pG.SetGlobalBuffer((__gm__ float *)probs, (uint64_t)ROWS * V);
    oG.SetGlobalBuffer((__gm__ float *)out, (uint64_t)ROWS * V);
    tG.SetGlobalBuffer((__gm__ float *)topp, 32);

    LocalTensor<uint8_t> mask = bMask.Get<uint8_t>();
    LocalTensor<float> zero = bZero.Get<float>();
    LocalTensor<float> tmp = bTmp.Get<float>();
    LocalTensor<float> acc = bAcc.Get<float>();
    LocalTensor<float> red = bRed.Get<float>();
    LocalTensor<float> scal = bScal.Get<float>();
    LocalTensor<float> tv = bTopp.Get<float>();

    Duplicate(zero, 0.0f, CH);
    DataCopy(tv, tG, 32);
    SetFlag<HardEvent::MTE2_S>(0);
    WaitFlag<HardEvent::MTE2_S>(0);
    float topP = tv.GetValue(row);

    uint32_t kLo = KEY_LO;
    uint32_t kHi = KEY_HI;
    float winHi = 0.0f;
    float winLo = 0.0f;

    for (int32_t r = 0; r < NROUND; r++) {
        if (kHi <= kLo + 1) {
            break;
        }
        uint32_t span = kHi - kLo;
        uint32_t step = span / (uint32_t)(NK + 1);
        if (step == 0) {
            step = 1;
        }
        float thr[NK];
        uint32_t keyv[NK];
        for (int32_t j = 0; j < NK; j++) {
            keyv[j] = kLo + step * (uint32_t)(j + 1);
            if (keyv[j] >= kHi) {
                keyv[j] = kHi - 1;
            }
            thr[j] = KeyToFloat(keyv[j]);
        }
        for (int32_t j = 0; j < NK; j++) {
            Duplicate(acc[j * CH], 0.0f, CH);
        }
        for (uint32_t off = 0; off < V; off += CH) {
            uint32_t n = (V - off < CH) ? (V - off) : CH;
            LocalTensor<float> x = inQ.AllocTensor<float>();
            if (n == CH) {
                DataCopy(x, pG[(uint64_t)row * V + off], CH);
            } else {
                DataCopyExtParams cp{1, (uint32_t)(n * sizeof(float)), 0, 0, 0};
                DataCopyPadExtParams<float> pad{false, 0, 0, 0};
                DataCopyPad(x, pG[(uint64_t)row * V + off], cp, pad);
            }
            inQ.EnQue(x);
            LocalTensor<float> xv = inQ.DeQue<float>();
            for (int32_t j = 0; j < NK; j++) {
                Compares(mask, xv, thr[j], CMPMODE::GE, n);
                Select(tmp, mask, xv, zero, SELMODE::VSEL_TENSOR_TENSOR_MODE, n);
                Add(acc[j * CH], acc[j * CH], tmp, n);
            }
            inQ.FreeTensor(xv);
        }
        for (int32_t j = 0; j < NK; j++) {
            float hi = 0.0f, lo = 0.0f;
            ReduceToScalar(acc[j * CH], red, hi, lo);
            float d = hi - topP;
            if (d + lo >= 0.0f) {
                kLo = keyv[j];
                winHi = hi;
                winLo = lo;
            } else {
                if (keyv[j] < kHi) {
                    kHi = keyv[j];
                }
            }
        }
    }

    float rSum = winHi + winLo;
    float invR = 1.0f / rSum;
    uint32_t cutoffKey = kLo;
    LocalTensor<int32_t> xKey = red.ReinterpretCast<int32_t>();
    for (uint32_t off = 0; off < V; off += CH) {
        uint32_t n = (V - off < CH) ? (V - off) : CH;
        LocalTensor<float> x = inQ.AllocTensor<float>();
        if (n == CH) {
            DataCopy(x, pG[(uint64_t)row * V + off], CH);
        } else {
            DataCopyExtParams cp{1, (uint32_t)(n * sizeof(float)), 0, 0, 0};
            DataCopyPadExtParams<float> pad{false, 0, 0, 0};
            DataCopyPad(x, pG[(uint64_t)row * V + off], cp, pad);
        }
        inQ.EnQue(x);
        LocalTensor<float> xv = inQ.DeQue<float>();
        LocalTensor<int32_t> kv = xv.ReinterpretCast<int32_t>();
        Compares(mask, kv, (int32_t)cutoffKey, CMPMODE::GE, n);
        Select(xv, mask, xv, zero, SELMODE::VSEL_TENSOR_TENSOR_MODE, n);
        Muls(xv, xv, invR, n);
        DataCopy(oG[(uint64_t)row * V + off], xv, n);
        inQ.FreeTensor(xv);
    }
    (void)scal;
    (void)xKey;
}

void kernel(torch::Tensor probs, torch::Tensor top_p, torch::Tensor out)
{
    TORCH_CHECK(probs.device().type() == c10::DeviceType::PrivateUse1, "npu tensor required");
    c10::DeviceGuard guard(probs.device());
    aclrtStream stream = c10_npu::getCurrentNPUStream(probs.get_device()).stream(true);
    top_p_kernel<<<ROWS, nullptr, stream>>>((GM_ADDR)probs.data_ptr(), (GM_ADDR)top_p.data_ptr(),
                                            (GM_ADDR)out.data_ptr());
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module)
{
    module.def("kernel", &kernel);
}
