import numpy as np
p = np.load('/tmp/probs.npy'); f32 = np.float32
V, CH, LANES = 128256, 2048, 64
NT = V // CH

def pred(row, t, finish):
    acc = np.zeros(CH, dtype=np.float32)
    for ti in range(NT + 1):
        seg = row[ti*CH:(ti+1)*CH]
        if seg.shape[0] < CH:
            s = np.zeros(CH, dtype=np.float32); s[:seg.shape[0]] = seg; seg = s
        acc = (acc + np.where(seg >= f32(t), seg, f32(0)).astype(np.float32)).astype(np.float32)
    a = acc.copy(); n = CH
    while n > LANES:
        n //= 2
        a[:n] = (a[:n] + a[n:2*n]).astype(np.float32)
    top = f32(0.9)
    if finish == 'f64':
        s = np.float64(0)
        for v in a[:LANES]: s += np.float64(v)
        return bool(s >= np.float64(top)), None
    if finish == 'naive':
        s = f32(0)
        for v in a[:LANES]: s = (s + v).astype(np.float32)
        return bool(s >= top), None
    # neumaier, exact comparison: (hi,lo) pair
    hi = f32(0); lo = f32(0)
    for v in a[:LANES]:
        s = (hi + v).astype(np.float32)
        if abs(hi) >= abs(v):
            e = ((hi - s).astype(np.float32) + v).astype(np.float32)
        else:
            e = ((v - s).astype(np.float32) + hi).astype(np.float32)
        lo = (lo + e).astype(np.float32)
        hi = s
    d = (top - hi).astype(np.float32)   # Sterbenz-exact when hi within factor 2 of top
    return bool(lo >= d), (hi, lo)

def f2k(f): return np.frombuffer(np.float32(f).tobytes(), dtype=np.uint32)[0]
def k2f(k): return float(np.frombuffer(np.uint32(k).tobytes(), dtype=np.float32)[0])

def search(row, finish):
    lo, hi = 0, 0x7F800000
    while hi - lo > 1:
        mid = lo + (hi - lo)//2
        ok, _ = pred(row, k2f(mid), finish)
        if ok: lo = mid
        else: hi = mid
    return lo

top64 = np.float64(np.float32(0.9))
for finish in ['naive','neumaier','f64']:
    bad = []
    for r in range(32):
        row = p[r]
        o = np.sort(row)[::-1].astype(np.float64); c = np.cumsum(o)
        i = int(np.searchsorted(c, top64, 'left')); tk = f2k(np.float32(o[i]))
        if search(row, finish) "'!= tk: bad.append(r)
    print(finish, '"'mismatch rows:', bad)
